const pathIcons={'Web Development':'code-2','Cybersecurity':'shield-check','Data Analytics':'chart-no-axes-combined','Accounting':'calculator','Marketing':'megaphone','Mechanical Design':'cog','UI/UX Design':'pen-tool'};
const icon=(name)=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
function dashboard(p){
 return `<div class="heading entry"><div><div class="eyebrow">THE NEXT VERSION OF YOU STARTS HERE</div><h1>Make your next move, ${esc(state.name)}.</h1><p>A little curiosity. A little courage. A step closer.</p></div><div class="streak">${icon('flame')}<div><strong>${count()?'Momentum found':'Your day one'}</strong><small>${count()?'Keep exploring':'Make it count'}</small></div></div></div>
 <div class="chapter-strip entry"><strong>01 / YOUR LAUNCHPAD</strong><span>${esc(state.path.toUpperCase())}</span><span>ONE MISSION AT A TIME</span></div>
 <section class="hero entry"><div class="hero-copy"><span class="pill">YOUR FUTURE IS UNWRITTEN</span><h2>${done()?'You learned it.<br>Now <em>make it real.</em>':'Less someday.<br>More <em>day one.</em>'}</h2><p>${done()?'Turn your new understanding into something you can show. Your next chapter starts with a project.':`Your next chapter starts with ${esc(p.skill.toLowerCase())}. Learn a little. Try it yourself. See what you’re capable of.`}</p><button class="primary" data-action="${done()?'projects':'lesson'}">${done()?'Build your first project':'Launch your first mission'} ${icon('arrow-up-right')}</button><span class="mission-time">${done()?'Ideas into evidence':'5 min · Beginner friendly'}</span></div><div class="hero-coordinate"><b>EXPLORE. BUILD. BECOME.</b>A PERSONAL JOURNEY / AN OPEN FUTURE</div></section>
 <div class="stats">${[
 ['route',`${done()?1:0}<span class="stat-number-suffix"> / 5</span>`,'Journey milestones'],
 ['zap',count()*50,'Learning XP earned'],['layers-3',state.projects.length,'Projects in progress'],['badge-check',count(),'Knowledge checks passed']
 ].map(([i,n,label])=>`<div class="stat entry"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><small>${label}</small></div></div>`).join('')}</div>
 <div class="columns"><section class="entry"><div class="section-head"><h2><span class="section-index">02</span>Your skill trajectory</h2><button class="text-button" data-action="roadmap">Full roadmap ↗</button></div><div class="card"><div class="path-top"><span class="tag">${esc(state.year.toUpperCase())} · YOUR CURRENT PATH</span>${icon(pathIcons[state.path])}</div><h3>${esc(state.path)}</h3><p>${p.desc}</p><div class="progress"><div style="width:${done()?20:0}%"></div></div><div class="progress-label"><span>${done()?'First checkpoint reached':'A new beginning'}</span><span>${done()?20:0}% complete</span></div>${p.steps.slice(0,3).map((s,i)=>`<div class="milestone"><span class="node ${i===0?'current':''}">${i===0&&done()?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${s}</strong><small>${i===0?(done()?'Introductory check completed':'Your next mission · Available now'):'Upcoming chapter · In preparation'}</small></div>${i===0?`<button data-action="lesson">${done()?'Revisit':'Begin ↗'}</button>`:''}</div>`).join('')}</div></section>
 <section class="entry"><div class="section-head"><h2><span class="section-index">03</span>The bigger picture</h2><span style="color:#8ba56a">✧</span></div><div class="card note-card"><div class="mini-label">A REMINDER FOR THE ROAD</div><h3>Great futures aren’t found.<br>They’re built.</h3><p>You don’t need the whole plan today. Follow your curiosity and give the next small step a chance.</p><button class="text-button" data-action="explore">Discover your direction ↗</button></div><div class="below"><div class="card"><div class="mini-label">FROM LEARNING TO DOING</div><h3>${p.project}</h3><p>Make something that tells your story.</p><button class="text-button" data-action="projects">Open project workspace ↗</button></div></div></section></div>`;
}
let focusRemaining=25*60,focusInterval=null;
function syncFocus(){const b=document.querySelector('#focus-start'),t=document.querySelector('#focus-time');if(t)t.textContent=`${String(Math.floor(focusRemaining/60)).padStart(2,'0')}:${String(focusRemaining%60).padStart(2,'0')}`;if(b)b.textContent=focusInterval?'Pause session':focusRemaining<1500?'Resume session':'Start focus session';document.body.classList.toggle('focus-on',!!focusInterval)}
function toggleFocus(){if(focusInterval){clearInterval(focusInterval);focusInterval=null}else{if(focusRemaining===0)focusRemaining=1500;focusInterval=setInterval(()=>{focusRemaining--;if(focusRemaining<=0){clearInterval(focusInterval);focusInterval=null;toast('Focus session complete. Take a moment to recharge.')}syncFocus()},1000)}syncFocus()}
function setupMotion(){let off=window.matchMedia('(prefers-reduced-motion: reduce)').matches;try{const stored=localStorage.getItem('nextstep-motion');if(stored!==null)off=stored==='off'}catch{}const b=document.querySelector('#motion-toggle');const sync=()=>{document.body.classList.toggle('motion-off',off);b.setAttribute('aria-pressed',String(!off));b.setAttribute('aria-label',off?'Enable cinematic motion':'Pause cinematic motion');b.innerHTML=icon(off?'play':'pause')+`<span>Motion ${off?'off':'on'}</span>`;window.lucide?.createIcons()};b.onclick=()=>{off=!off;try{localStorage.setItem('nextstep-motion',off?'off':'on')}catch{}sync()};sync()}
